/// <summary>
/// Service class for the intercompany PO vendor invoice.
/// </summary>
public class METIntercompanyPOVendInvoiceService extends SysOperationServiceBase
{
    #OCCRetryCount

}

Method.Source:
/// <summary>
/// Submit the pending vendor invoices to workflow
/// </summary>
/// <param name = "_invoiceSet">List of invoices to submit</param>
private void submitInvoices(Set _invoiceSet)
{
    SetEnumerator invoiceSetEnumerator;

    if (!_invoiceSet.empty())
    {
        invoiceSetEnumerator = _invoiceSet.getEnumerator();
        invoiceSetEnumerator.reset();

        while (invoiceSetEnumerator.moveNext())
        {
            VendInvoiceInfoTable infoTable = invoiceSetEnumerator.current();
            try
            {
                this.submitInvoiceToWorkflow(infoTable);
            }
            catch
            {
                warning(strFmt('@MET:METInterCoInvoiceSubmitWFError', infoTable.Num));
                continue;
            }
        }
    }
}

/// <summary>
/// Process method for PO fulfillment.
/// </summary>
/// <param name = "_contract">METIntercompanyPOFulfillmentContract</param>
public void processIntercompanyPOFulfillment(METIntercompanyPOFulfillmentContract _contract)
{
    Query       query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun    queryRun    = new QueryRun(query);
    Set         invoiceSet  = new Set(Types::Record);

    while (queryRun.next())
    {
        SalesId                 metFulfillmentSOReference;
        PurchLine               purchLine   = queryRun.get(tableNum(PurchLine));
        PurchTable              purchTable  = queryRun.get(tableNum(PurchTable));
        CustInvoiceJour         custInvoiceJour;
        VendInvoiceJour         vendInvoiceJour;
        VendPackingSlipJour     vendPackingSlipJour;
        VendInvoiceInfoTable    vendInvoiceInfoTableLoc;
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        SalesLine               salesLine;
        InterCompanyCompanyId   interCompanyCompanyId;

        metFulfillmentSOReference   = purchTable.InterCompanySalesId;
        interCompanyCompanyId       = purchTable.InterCompanyCompanyId;

        if (purchLine.IsDeleted == NoYes::Yes)
        {
            continue;
        }

        //Find the related sales line and customer invoice journal in another legal entity.
        changecompany(interCompanyCompanyId)
        {
            salesLine = this.findSalesLine(purchLine, metFulfillmentSOReference);

            if (salesLine.SalesStatus == SalesStatus::Invoiced)
            {
                custInvoiceJour = this.findCustInvoiceJour(salesLine);
            }
        }

        try
        {
            //Create the pending vendor invoice
            if (custInvoiceJour)
            {
                vendInvoiceInfoTableLoc = this.createPendingVendorInvoice(purchLine, salesLine, interCompanyCompanyId);

                info(strFmt("@MET:METPendingVendInvoiceCreatedInfo", vendInvoiceInfoTableLoc.Num, purchTable.PurchId));

                if(!invoiceSet.in(vendInvoiceInfoTableLoc))
                {
                    invoiceSet.add(vendInvoiceInfoTableLoc);
                }
            }
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    this.submitInvoices(invoiceSet);
}

/// <summary>
///Process method for the PO replenishment.
/// </summary>
/// <param name = "_contract">METIntercompanyPOReplenishmentContract</param>
public void processIntercompanyPOReplenishment(METIntercompanyPOReplenishmentContract _contract)
{
    Query                   query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun                queryRun    = new QueryRun(query);
    InterCompanyCompanyId   interCompanyCompanyId = InventParameters::find().METInternalCustLegelEntity;
    Set                     invoiceSet  = new Set(Types::Record);

    while (queryRun.next())
    {
        PurchLine               purchLine   = queryRun.get(tableNum(PurchLine));
        PurchTable              purchTable  = queryRun.get(tableNum(PurchTable));
        CustInvoiceJour         custInvoiceJour;
        VendInvoiceJour         vendInvoiceJour;
        VendPackingSlipJour     vendPackingSlipJour;
        VendInvoiceInfoTable    vendInvoiceInfoTableLoc;
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        SalesLine               salesLine;

        if (purchLine.IsDeleted == NoYes::Yes)
        {
            continue;
        }

        //Find the related sales line and customer invoice journal in another legal entity.
        changecompany(interCompanyCompanyId)
        {
            salesLine = this.findSalesLine(purchLine, purchLine.METReplenishmentSOReference);

            if (salesLine.SalesStatus == SalesStatus::Invoiced)
            {
                custInvoiceJour = this.findCustInvoiceJour(salesLine);
            }
        }

        try
        {
            //Create the pending vendor invoice
            if (custInvoiceJour)
            {
                ttsbegin;
                vendInvoiceInfoTableLoc = this.createPendingVendorInvoice(purchLine, salesLine, interCompanyCompanyId);
                ttscommit;

                info(strFmt("@MET:METPendingVendInvoiceCreatedInfo", vendInvoiceInfoTableLoc.Num, purchTable.PurchId));

                if(!invoiceSet.in(vendInvoiceInfoTableLoc))
                {
                    invoiceSet.add(vendInvoiceInfoTableLoc);
                }
            }
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    this.submitInvoices(invoiceSet);
}

/// <summary>
/// Finds the customer invoice journal for the given sales line.
/// </summary>
/// <param name="_salesLine">The sales line to find the invoice journal for.</param>
/// <returns>The related CustInvoiceJour record, or null if not found.</returns>
public CustInvoiceJour findCustInvoiceJour(SalesLine _salesLine)
{
    CustInvoiceJour         custInvoiceJour = null;
    CustInvoiceTrans        custInvoiceTrans;

    select firstonly custInvoiceJour
        order by custInvoiceJour.InvoiceDate desc
        join custInvoiceTrans
        where custInvoiceJour.RecId == custInvoiceTrans.ParentRecId
            && custInvoiceTrans.InventTransId == _salesLine.InventTransId;

    return custInvoiceJour;
}

/// <summary>
/// Finds the sales line that matches the given purchase line based on replenishment reference and inventory dimensions.
/// </summary>
/// <param name="_purchline">The purchase line to match.</param>
/// <returns>The related SalesLine record, or null if not found.</returns>
public SalesLine findSalesLine(PurchLine _purchline, SalesId _metSOReference)
{
    SalesLine               salesLine = null;
    InventDim               purchInventDim, salesInventDim;

    purchInventDim = InventDim::find(_purchline.InventDimId);

    select firstonly salesLine
        where  salesLine.SalesId == _metSOReference
            && salesLine.ItemId == _purchline.ItemId
            && salesLine.SalesUnit == _purchline.PurchUnit
        join salesInventDim
        where  salesInventDim.inventBatchId == purchInventDim.inventBatchId
            && salesInventDim.InventSiteId == purchInventDim.InventSiteId
            && salesInventDim.InventLocationId == purchInventDim.InventLocationId
            && salesInventDim.wMSLocationId == purchInventDim.wMSLocationId;

    return salesLine;
}

/// <summary>
/// Create the pending vendor invoice of the PO.
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
/// <returns></returns>
public VendInvoiceInfoTable createPendingVendorInvoice(PurchLine _purchLine, SalesLine _salesLine,  InterCompanyCompanyId   _interCompanyCompanyId)
{
    PurchTable              purchTable      = PurchTable::find(_purchLine.PurchId);
    CustInvoiceJour         custInvoiceJour;
    CustInvoiceTrans        custInvoiceTrans;
    VendPackingSlipJour     vendPackingSlipJour;
    VendInvoiceInfoTable    vendInvoiceInfoTable;

    changecompany(_interCompanyCompanyId)
    {
        custInvoiceJour = this.findCustInvoiceJour(_salesLine);

        // FIX: pick the matching sales invoice line for this PO line (by InventTransId)
        select firstonly custInvoiceTrans
            where custInvoiceTrans.ParentRecId == custInvoiceJour.RecId
            && custInvoiceTrans.InventTransId == _salesLine.InventTransId;
    }

    select firstonly vendInvoiceInfoTable
        where vendInvoiceInfoTable.PurchId == purchTable.PurchId
        && vendInvoiceInfoTable.Num == custInvoiceJour.InvoiceId;

    if (!vendInvoiceInfoTable.RecId)
    {
        vendInvoiceInfoTable.clear();
        vendInvoiceInfoTable.initValue();
        vendInvoiceInfoTable.initFromPurchTable(purchTable);
        vendInvoiceInfoTable.DocumentOrigin = DocumentOrigin::Manual;
        vendInvoiceInfoTable.defaultRow(null, null, true);

        vendInvoiceInfoTable.Num                        = custInvoiceJour.InvoiceId;
        vendInvoiceInfoTable.ParmId                     = formletterParmData::getNewParmId();
        vendInvoiceInfoTable.Payment                    = VendTable::find(purchTable.InvoiceAccount).PaymTermId;
        vendInvoiceInfoTable.Approved                   = NoYes::Yes;
        vendInvoiceInfoTable.TableRefId                 = formletterParmData::getNewTableRefId();
        vendInvoiceInfoTable.Description                = _salesLine.SalesId;
        vendInvoiceInfoTable.MetImportGST               = custInvoiceJour.SumTax;

        vendInvoiceInfoTable.DocumentDate               = this.hasMultipleProductReceipts(purchTable.PurchId)
                                                        ? this.invoiceDateForMultipleReceipt(vendInvoiceInfoTable)
                                                        : custInvoiceJour.InvoiceDate;

        vendInvoiceInfoTable.MetImportAmount            = custInvoiceJour.InvoiceAmount;

        // Saving or Posting will update this value, at this point we only want to flag that the value is something other than LastMatchVarianceOptions::Unknown
        vendInvoiceInfoTable.LastMatchVariance          = LastMatchVarianceOptions::OK;

        vendInvoiceInfoTable.PerformFullInvoiceMatching = NoYes::Yes;

        if (vendInvoiceInfoTable.validateWrite())
        {
            VendInvoiceInfoSubTable::createFromVendInvoiceInfoTable(vendInvoiceInfoTable, true);
            vendInvoiceInfoTable.insert();
        }
    }

    // Only create lines if the matching invoice transaction exists
    if (custInvoiceTrans)
    {
        this.createPendingVendorInvoiceLines(vendInvoiceInfoTable, _purchLine, custInvoiceTrans);
    }

    return vendInvoiceInfoTable;
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <param name = "_purchLine">PurchLine</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
public void createPendingVendorInvoiceLines(VendInvoiceInfoTable _vendInvoiceInfoTable,
                                        PurchLine _purchLine, CustInvoiceTrans _custInvoiceTrans)
{
    VendInvoiceInfoLine     vendInvoiceInfoLine;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

    select firstonly vendInvoiceInfoLine
        where vendInvoiceInfoLine.ParmId == _vendInvoiceInfoTable.ParmId
            && vendInvoiceInfoLine.TableRefId == _vendInvoiceInfoTable.TableRefId
            && vendInvoiceInfoLine.ItemId == _purchLine.ItemId
            && vendInvoiceInfoLine.PurchUnit == _purchLine.PurchUnit;

    if (!vendInvoiceInfoLine.RecId)
    {
        vendInvoiceInfoLine.clear();
        vendInvoiceInfoLine.initValue();
        vendInvoiceInfoLine.initFromPurchLine(_purchLine);

        // FIX: drive invoice quantities from the intercompany customer invoice line (not the PO ordered qty)
        // This avoids “inventory quantity is not equal to PO quantity” at posting.
        vendInvoiceInfoLine.ItemId              = _purchLine.ItemId;
        vendInvoiceInfoLine.ParmId              = _vendInvoiceInfoTable.ParmId;
        vendInvoiceInfoLine.PurchUnit           = _purchLine.PurchUnit;

        // Use invoiced quantity on both InventNow and ReceiveNow to match packing slip distribution we create below
        vendInvoiceInfoLine.ReceiveNow          = _custInvoiceTrans.Qty;
        vendInvoiceInfoLine.InventNow           = _custInvoiceTrans.InventQty;

        // Price from intercompany sales invoice line
        vendInvoiceInfoLine.PurchPrice          = _custInvoiceTrans.SalesPrice;
        vendInvoiceInfoLine.PriceUnit           = _custInvoiceTrans.PriceUnit;
        vendInvoiceInfoLine.LineAmount          = _custInvoiceTrans.LineAmount;

        vendInvoiceInfoLine.TableRefId          = _vendInvoiceInfoTable.TableRefId;
        vendInvoiceInfoLine.DeliveryName        = _vendInvoiceInfoTable.DeliveryName;
        vendInvoiceInfoLine.currencyCode        = _vendInvoiceInfoTable.CurrencyCode;
        vendInvoiceInfoLine.OrderAccount        = _vendInvoiceInfoTable.OrderAccount;
        vendInvoiceInfoLine.DocumentOrigin      = DocumentOrigin::Manual;
        vendInvoiceInfoLine.InvoiceAccount      = _vendInvoiceInfoTable.InvoiceAccount;

        vendInvoiceInfoLine.ProcurementCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(_purchLine.ItemId, EcoResCategoryNamedHierarchyRole::Procurement).Category;

        //Force trigger variance calculation on lines.
        if(vendInvoiceInfoLine.isNonPO())
        {
            vendInvoiceInfoLine.metFetchInitializeReasonCode();
        }

        vendInvoiceInfoLine.insert();

        if (vendInvoiceInfoLine.RecId)
        {
            // FIX: distribute packing slip quantities up to the invoiced quantity only
            this.createPendingVendorInvoiceInfoSubLines(_purchLine.InventTransId, 
                vendInvoiceInfoLine, 
                _custInvoiceTrans.PdsCWQty);

            this.metUpdateReceiptedData(vendInvoiceInfoLine, _purchLine);

            PurchFormletterParmDataInvoice::createVendInvoiceMatchingLineForServices(
                    vendInvoiceInfoLine,
                    vendInvoiceInfoLine.purchLine(),
                    vendInvoiceInfoLine.vendInvoiceInfoTable().VarianceApproved,
                    true);
        }
    }
}

/// <summary>
/// Update the receipted data on the vendor invoice info line.
/// </summary>
/// <param name = "_vendInvoiceInfoLine">Pending vendor invoice line</param>
/// <param name = "_purchLine">PO line</param>
protected void metUpdateReceiptedData(VendInvoiceInfoLine _vendInvoiceInfoLine, PurchLine _purchLine)
{
    ReasonTable reason;

    ttsbegin;
    _vendInvoiceInfoLine.reread();
    _vendInvoiceInfoLine.selectForUpdate(true);
    _vendInvoiceInfoLine.METReceiptedUnit           = _purchLine.PurchPrice;
    _vendInvoiceInfoLine.METReceiptedQuantity       = _vendInvoiceInfoLine.purchQtyMatched();
    _vendInvoiceInfoLine.METReceiptedCWQuantity     = _vendInvoiceInfoLine.pdsCWQtyMatched();// sumCWQtyMap.lookup(key);
    _vendInvoiceInfoLine.METReceiptedLineNetAmount  = _vendInvoiceInfoLine.METReceiptedQuantity * _purchLine.PurchPrice; //sumValueMap.lookup(key);

    _vendInvoiceInfoLine.update();
    ttscommit;
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <param name = "_purchLine">PurchLine</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
// New helper: cap subline quantities to match the invoice line’s quantity
private void createPendingVendorInvoiceInfoSubLines(InventTransId _inventTransId, 
    VendInvoiceInfoLine _vendInvoiceInfoLine, PdsCWInventQty _pdsCWInventQty)
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

    while select InventTransId, PackingSlipId, Qty, RecId, TableId from vendPackingSlipTrans
            where vendPackingSlipTrans.InventTransId == _inventTransId
    {
        vendInvoiceInfoSubLine.clear();
        vendInvoiceInfoSubLine.initValue();
        vendInvoiceInfoSubLine.defaultRow();

        vendInvoiceInfoSubLine.ParmId               = _vendInvoiceInfoLine.ParmId;
        vendInvoiceInfoSubLine.InventNow            = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.ReceiveNow           = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.PdsCWInventNow       = _pdsCWInventQty;
        vendInvoiceInfoSubLine.DocumentId           = vendPackingSlipTrans.PackingSlipId;
        vendInvoiceInfoSubLine.LineRefRecId         = _vendInvoiceInfoLine.RecId;
        vendInvoiceInfoSubLine.JournalRefRecId      = vendPackingSlipTrans.RecId;
        vendInvoiceInfoSubLine.JournalRefTableId    = vendPackingSlipTrans.TableId;

        vendInvoiceInfoSubLine.insert();
    }
}

/// <summary>
/// Get the invoice date from the receipts.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <returns>InvoiceDate</returns>
public InvoiceDate invoiceDateForMultipleReceipt(VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    InvoiceDate            invoiceDate;
    VendPackingSlipJour     vendPackingSlipJour;
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
    VendInvoiceInfoLine     vendInvoiceInfoLine;

    if (VendParameters::find().METDefaultInvDate)
    {
        select firstonly DeliveryDate from vendPackingSlipJour order by DeliveryDate asc
            exists join vendPackingSlipTrans
            where vendPackingSlipTrans.VendPackingSlipJour == vendPackingSlipJour.RecId
                exists join VendInvoiceInfoSubLine
                where VendInvoiceInfoSubLine.JournalRefRecId == vendPackingSlipTrans.RecId
                && VendInvoiceInfoSubLine.JournalRefTableId == tableNum(VendPackingSlipTrans)
                    exists join vendInvoiceInfoLine
                    where vendInvoiceInfoLine.RecId == VendInvoiceInfoSubLine.LineRefRecId
                    && vendInvoiceInfoLine.ParmId == _vendInvoiceInfoTable.ParmId
                    && vendInvoiceInfoLine.TableRefId == _vendInvoiceInfoTable.TableRefId;

        if (vendPackingSlipJour && vendPackingSlipJour.DeliveryDate != _vendInvoiceInfoTable.DocumentDate)
        {
            invoiceDate = vendPackingSlipJour.DeliveryDate;
        }
    }
    return invoiceDate;
}

/// <summary>
/// Check if there are multiple product receipts for the purchase order.
/// </summary>
/// <param name = "_purchId">PurchId</param>
/// <returns>Ture/false</returns>
public boolean hasMultipleProductReceipts(PurchId _purchId)
{
    VendPackingSlipJour vendPackingSlipJour;

    // Count packing slip journal records that reference the PurchId.
    // The "select count(RecId)" returns the count in vendPackingSlipJour.RecId.
    select count(RecId) from vendPackingSlipJour
        where vendPackingSlipJour.PurchId == _purchId;

    return vendPackingSlipJour.RecId > 1;
}

/// <summary>
/// Get the reason code for the variance type.
/// </summary>
/// <param name = "_varianceType">Variance type</param>
/// <param name = "_createClaim">True/false</param>
/// <returns>Reason code</returns>
public ReasonTable getReasonCodeForVarianceType(METVarianceType _varianceType, NoYes _claim)
{
    ReasonTable reason;

    select firstonly reason
        where reason.METVarianceType == _varianceType
        && reason.METInvoiceMatch == NoYes::Yes
        && reason.METClaim == _claim;

    return reason;
}

/// <summary>
/// Submit Invoice to workflow.
/// </summary>
/// <param name = "_invoiceTable">VendInvoiceInfoTable</param>
private void submitInvoiceToWorkflow(VendInvoiceInfoTable _invoiceTable)
{
    if(_invoiceTable && _invoiceTable.existLine() && _invoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_invoiceTable, _invoiceTable.Description);
    }
}
